    ByteBuffer dup = bb.duplicate();
    dup.position(i);
    int start = i;
    int b1 = dup.get() & 0xFF;
    int codePoint = 0;
    int bytesNeeded = 0;

    if ((b1 & 0x80) == 0) {
        codePoint = b1;
        bytesNeeded = 1;
    } else if ((b1 & 0xE0) == 0xC0) {
        codePoint = b1 & 0x1F;
        bytesNeeded = 2;
    } else if ((b1 & 0xF0) == 0xE0) {
        codePoint = b1 & 0x0F;
        bytesNeeded = 3;
    } else if ((b1 & 0xF8) == 0xF0) {
        codePoint = b1 & 0x07;
        bytesNeeded = 4;
    } else {
        // Invalid first byte
        codePoint = 0xFFFD;
        bytesNeeded = 1;
    }

    for (int j = 1; j < bytesNeeded; j++) {
        int b = dup.get() & 0xFF;
        if ((b & 0xC0) != 0x80) {
            // Invalid continuation byte
            codePoint = 0xFFFD;
            bytesNeeded = j + 1;
            break;
        }
        codePoint = (codePoint << 6) | (b & 0x3F);
    }

